function normalize(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss').replace(/[^a-z0-9]+/g,' ').trim();}
var byId={};catalogue.forEach(function(e){byId[e.id]=e;});
function search(query,muscle,eq){var terms=normalize(query).split(' ').filter(Boolean),group=muscle==='arms'?['biceps','triceps','forearms']:muscle==='legs'?['quads','hamstrings','glutes','calves']:[muscle];return catalogue.filter(function(e){var hay=normalize(e.name+' '+e.aliases.join(' '));return (!muscle||group.some(function(m){return e.muscles.includes(m)||e.secondary.includes(m);}))&&(!eq||e.equipment===eq)&&terms.every(function(t){return hay.includes(t);});});}
function config(input){var c=Object.assign({},defaults,input||{});c.days=Math.max(1,Math.min(5,Math.round(Number(c.days)||3)));c.minutes=Math.max(30,Math.min(120,Math.round((Number(c.minutes)||60)/5)*5));c.years=Math.max(0,Number(c.years)||0);if(!['muscle','strength','max'].includes(c.goal))c.goal='muscle';if(!['beginner','intermediate','expert'].includes(c.level))c.level='beginner';if(!['machine','mixed','free'].includes(c.preference))c.preference='machine';c.priorities=Array.isArray(c.priorities)?c.priorities.filter(function(m,i,a){return muscles[m]&&a.indexOf(m)===i;}).slice(0,3):[];return c;}
function beginner(c){return c.level==='beginner'||c.years<1;}
function prescription(e,c){var novice=beginner(c),reps=c.goal==='muscle'?(e.main?[8,12]:[10,15]):c.goal==='strength'?(e.main?(novice?[6,10]:[5,8]):[10,15]):(e.main?(novice?[6,8]:[3,6]):[8,12]);return {catalogueId:e.id,name:e.name,sets:novice?2:(c.level==='expert'&&c.years>=3&&c.priorities.includes(e.muscles[0])?4:3),rmin:reps[0],rmax:reps[1],main:e.main,rest:e.main?(c.goal==='muscle'?120:c.goal==='strength'?150:180):90,targetMuscle:e.muscles[0]};}
function estimate(day,input){var c=config(input),rows=day.exercises.filter(function(e){return !e.empty;});return Math.ceil(((c.goal==='max'?720:480)+Math.max(0,rows.length-1)*90+rows.reduce(function(sum,e){return sum+e.sets*45+Math.max(0,e.sets-1)*(e.rest||90);},0))/60);}
function choose(m,c,used,offset){var options=catalogue.filter(function(e){return e.standard&&e.muscles[0]===m&&!used.includes(e.id)&&(!beginner(c)||e.beginner);});if(!options.length)return null;function rank(e){return c.preference==='machine'?(['machine','cable'].includes(e.equipment)?0:1):c.preference==='free'?(['barbell','dumbbell'].includes(e.equipment)?0:e.equipment==='bodyweight'?1:2):0;}options.sort(function(a,b){return rank(a)-rank(b)||Number(b.main)-Number(a.main)||a.id.localeCompare(b.id);});var best=options.filter(function(e){return rank(e)===rank(options[0]);});return best[offset%best.length];}
function create(templateId,input,empty){var c=config(input),t=templates.find(function(t){return t.id===templateId;})||templates[0],layout=t.id==='full'?t.layout.slice(0,Math.min(3,c.days)):t.layout;
if(t.id==='roman'){c.days=4;return {name:t.name,input:c,templateId:t.id,notice:'Originalvorlage: Passe Übungen, Umfang und Gewichte an dich an. Es werden keine persönlichen Trainingsdaten übernommen.',days:romanPlan.map(function(d){var day={name:d.name,exercises:d.exercises.map(function(e){return empty?{empty:true,targetMuscle:e.targetMuscle}:Object.assign({},e);})};day.minutes=empty?null:estimate(day,c);return day;})};}
var result={name:t.name,input:c,templateId:t.id,days:[],notice:c.years<1&&c.level!=='beginner'?'Für weniger als ein Jahr Trainingserfahrung verwenden wir zunächst einfache Standardübungen.':''};
layout.forEach(function(pair,index){var selected=[],used=[],targets=roles[pair[1]],day={name:pair[0],exercises:selected};targets.forEach(function(m){if(empty){selected.push({empty:true,targetMuscle:m});return;}var e=choose(m,c,used,index);if(e){used.push(e.id);selected.push(prescription(e,c));}});
if(!empty){c.priorities.forEach(function(m){if(!targets.includes(m)&&pair[1]!=='full'&&!(pair[1]==='upper'&&['abs','forearms'].includes(m))&&!(m==='forearms'&&targets.includes('biceps')))return;var e=choose(m,c,used,index+1);if(e){used.push(e.id);var row=prescription(e,c);row.optional=true;selected.push(row);}});
while(estimate(day,c)>c.minutes&&selected.some(function(e){return e.optional;})){var last=selected.map(function(e){return e.optional;}).lastIndexOf(true);selected.splice(last,1);}
while(estimate(day,c)>c.minutes&&selected.some(function(e){return e.sets>1;})){var candidates=selected.filter(function(e){return e.sets>1;}).sort(function(a,b){return Number(c.priorities.includes(a.targetMuscle))-Number(c.priorities.includes(b.targetMuscle))||b.sets-a.sets;});candidates[0].sets--;}
}day.minutes=empty?null:estimate(day,c);result.days.push(day);});return result;}
function generate(input){var c=config(input);return create(c.days<=3?'full':c.days===4?'ul':'ulppl',c,false);}
root.MinMaxStudio={catalogue:catalogue,muscles:muscles,equipment:equipment,templates:templates,defaults:defaults,byId:byId,normalize:normalize,search:search,config:config,estimate:estimate,create:create,generate:generate,prescription:prescription};
if(typeof module!=='undefined'&&module.exports)module.exports=root.MinMaxStudio;

